mapper.update:
update
    tb_routine_template_item
set
    exercise_item_name = #{exerciseItemName},
    sort_order = #{sortOrder},
    updated_at = NOW()
where
    template_item_id = #{templateItemId}
and (
    exercise_item_name <> #{exerciseItemName}
    or sort_order <> #{sortOrder}
    )

update
    tb_routine_template_set
set
    set_no = #{setNo},
    planned_reps = #{plannedReps},
    planned_weight_kg = #{plannedWeightKg},
    updated_at = NOW()
where
    template_set_id = #{templateSetId}
and (
    set_no <> #{setNo}
    or planned_reps <> #{plannedReps}
    or planned_weight_kg <> #{plannedWeightKg}
    )
